import{_ as a,c as t,o as s,ag as n}from"./chunks/framework.Bzez9NG9.js";const u=JSON.parse('{"title":"AI examples","description":"Explore practical SPACE AI use cases for understanding Planning Analytics models, analyzing TM1 and BigQuery data, troubleshooting issues, developing model objects, comparing environments, and using SPACE.","frontmatter":{"title":"AI examples","description":"Explore practical SPACE AI use cases for understanding Planning Analytics models, analyzing TM1 and BigQuery data, troubleshooting issues, developing model objects, comparing environments, and using SPACE.","keywords":["AI use cases","example questions","TM1","Planning Analytics","model analysis","data analysis","variance analysis","troubleshooting","rules","TurboIntegrator","TI","BigQuery","views","subsets","environment comparison","SPACE help"],"outline":"deep"},"headers":[],"relativePath":"doc/ai/examples.md","filePath":"doc/ai/examples.md"}'),i={name:"doc/ai/examples.md"};function o(l,e,p,d,c,h){return s(),t("div",null,e[0]||(e[0]=[n('<h1 id="ai-examples" tabindex="-1">AI examples <a class="header-anchor" href="#ai-examples" aria-label="Permalink to &quot;AI examples&quot;">​</a></h1><p>SPACE AI brings model understanding, data analysis, development, troubleshooting, and connected data into the same conversational workflow. You can start with a business question, a model object, an error, or a task and let the assistant use the relevant SPACE capabilities and connected systems.</p><p>The examples below show different ways SPACE AI can be used with IBM Planning Analytics. Exact results depend on your connections, permissions, model, and available data.</p><h2 id="understand-an-unfamiliar-planning-analytics-model" tabindex="-1">Understand an unfamiliar Planning Analytics model <a class="header-anchor" href="#understand-an-unfamiliar-planning-analytics-model" aria-label="Permalink to &quot;Understand an unfamiliar Planning Analytics model&quot;">​</a></h2><p>Instead of manually searching through cubes, dimensions, rules, and processes, start with what you need to understand.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain how revenue is calculated in this model.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which cubes, rules, and processes are involved in the forecast?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find everything related to headcount planning and explain how the pieces fit together.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Where is the Product dimension used?</span></span></code></pre></div><p>This is useful when onboarding to an unfamiliar model, reviewing inherited applications, investigating dependencies, or preparing to make a change.</p><p>See <a href="./models-and-logic.html">Models and logic</a>.</p><h2 id="understand-rules-and-feeders" tabindex="-1">Understand rules and feeders <a class="header-anchor" href="#understand-rules-and-feeders" aria-label="Permalink to &quot;Understand rules and feeders&quot;">​</a></h2><p>Ask SPACE AI to inspect existing rule logic and explain it at the level you need.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain the Sales cube rules and identify the main calculations.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How is Gross Margin calculated?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review the feeders for this cube and explain which calculations they support.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain this rule in business terms rather than TM1 syntax.</span></span></code></pre></div><p>You can continue from explanation into investigation or development without starting a separate workflow.</p><h2 id="understand-and-review-turbointegrator-processes" tabindex="-1">Understand and review TurboIntegrator processes <a class="header-anchor" href="#understand-and-review-turbointegrator-processes" aria-label="Permalink to &quot;Understand and review TurboIntegrator processes&quot;">​</a></h2><p>SPACE AI can inspect TI processes, explain their logic, and follow their dependencies.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain the Load_GL_Actuals process and summarize what each section does.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which cubes and dimensions does this process read from or update?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review this process and identify anything I should consider before modifying it.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find the process that loads actual revenue and explain the data flow.</span></span></code></pre></div><p>This can be especially useful when working with complex or poorly documented TM1 applications.</p><h2 id="analyze-tm1-data" tabindex="-1">Analyze TM1 data <a class="header-anchor" href="#analyze-tm1-data" aria-label="Permalink to &quot;Analyze TM1 data&quot;">​</a></h2><p>Start with a business question rather than constructing an MDX query manually.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare Actual and Forecast revenue by region for this quarter and show the largest variances.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which products contributed most to the decline in gross margin?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Show monthly operating expenses for the top five departments and summarize the trend.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find the entities with the largest variance to budget and help me investigate them.</span></span></code></pre></div><p>SPACE AI can inspect the model context, construct the required TM1 query, retrieve data in manageable result sets, and continue through larger results when needed.</p><p>You can also ask SPACE AI to visualize the results:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Show Actual and Forecast revenue by month as a chart.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Visualize the largest variances by department.</span></span></code></pre></div><p>When an analysis produces a useful result, save it as a TM1 cube view instead of leaving it only in the conversation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Save these results as a private view called Revenue Variance Analysis.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Save the last results as a public view called Monthly Forecast Review.</span></span></code></pre></div><p>The saved view can then be reused in IBM Planning Analytics Workspace or through SPACE and SPACE AI. Views are private by default unless you request a public view.</p><p>See <a href="./tm1-data.html">TM1 data</a>.</p><h2 id="move-from-a-variance-to-its-model-logic" tabindex="-1">Move from a variance to its model logic <a class="header-anchor" href="#move-from-a-variance-to-its-model-logic" aria-label="Permalink to &quot;Move from a variance to its model logic&quot;">​</a></h2><p>A data question does not have to end with the numbers. Continue the investigation into the model itself.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Why is this forecast significantly different from Actual?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which rules affect this value?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Is this value calculated, loaded by a process, or entered directly?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find the logic responsible for this result and explain it.</span></span></code></pre></div><p>This connects data analysis with model understanding and can help distinguish a business variance from a modeling or data-loading issue.</p><h2 id="investigate-tm1-errors" tabindex="-1">Investigate TM1 errors <a class="header-anchor" href="#investigate-tm1-errors" aria-label="Permalink to &quot;Investigate TM1 errors&quot;">​</a></h2><p>Start with the symptom rather than manually deciding which log or object to inspect.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This TurboIntegrator process failed last night. Find out why.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Investigate this TM1 error and explain the likely cause.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check the relevant server logs and process logic for this failure.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A value changed unexpectedly yesterday. Help me determine what changed it.</span></span></code></pre></div><p>Depending on the problem, SPACE AI can use TM1 server, transaction, or audit information together with related model objects and logic.</p><p>See <a href="./investigating-errors.html">Investigating errors</a>.</p><h2 id="investigate-space-errors" tabindex="-1">Investigate SPACE errors <a class="header-anchor" href="#investigate-space-errors" aria-label="Permalink to &quot;Investigate SPACE errors&quot;">​</a></h2><p>SPACE AI can also help troubleshoot SPACE itself.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I received this error in the AI Assistant about 20 minutes ago. What happened?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This SPACE operation failed. Search the relevant logs and investigate it.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find this error in the logs and follow the related trace.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Why did this scheduled job fail?</span></span></code></pre></div><p>The assistant can use available SPACE application logs and Journal information, and can follow trace IDs when they are available to locate related application activity.</p><h2 id="create-and-modify-tm1-objects" tabindex="-1">Create and modify TM1 objects <a class="header-anchor" href="#create-and-modify-tm1-objects" aria-label="Permalink to &quot;Create and modify TM1 objects&quot;">​</a></h2><p>SPACE AI is not limited to explaining existing models. It can perform supported development tasks when the user has the required access.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a private view showing Actual and Budget revenue by month for the current year.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a subset containing the active cost centers.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Update this TI process to include the new scenario.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Modify the rule to calculate the new measure using the existing pattern.</span></span></code></pre></div><p>SPACE supports creating and updating rules, TurboIntegrator processes, views, and subsets through the AI Assistant. Views and subsets are private by default unless you request a public object.</p><p>Review and test model changes using the normal development practices for your environment.</p><h2 id="work-across-planning-analytics-environments" tabindex="-1">Work across Planning Analytics environments <a class="header-anchor" href="#work-across-planning-analytics-environments" aria-label="Permalink to &quot;Work across Planning Analytics environments&quot;">​</a></h2><p>When multiple TM1 connections are available, the same conversation can work with more than one environment.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare this rule between Development and Production.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Is this TI process the same in Test and Production? Explain the differences.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare this data between the two environments and identify the differences.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check whether the objects related to this change are consistent between Development and Production.</span></span></code></pre></div><p>For lifecycle workflows specifically designed to compare environments and manage changes, see <a href="./../planning-analytics/releases-and-deployments.html">Releases and deployments</a>.</p><h2 id="combine-planning-analytics-and-bigquery-data" tabindex="-1">Combine Planning Analytics and BigQuery data <a class="header-anchor" href="#combine-planning-analytics-and-bigquery-data" aria-label="Permalink to &quot;Combine Planning Analytics and BigQuery data&quot;">​</a></h2><p>SPACE AI can work with native Google BigQuery connections alongside TM1.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare the forecast in TM1 with actual sales from BigQuery.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use the detailed BigQuery data to investigate this variance in Planning Analytics.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Show the largest differences between the TM1 plan and the operational data in BigQuery.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start with this TM1 result, then find the related transactions in BigQuery and summarize what explains the difference.</span></span></code></pre></div><p>This allows planning and model context from IBM Planning Analytics to be analyzed together with supporting data from another connected source.</p><p>See <a href="./connected-data.html">Connected data</a>.</p><h2 id="use-your-existing-identity-and-security" tabindex="-1">Use your existing identity and security <a class="header-anchor" href="#use-your-existing-identity-and-security" aria-label="Permalink to &quot;Use your existing identity and security&quot;">​</a></h2><p>IBM Planning Analytics and Google BigQuery connections can use SSO, allowing SPACE AI to work with connected data using the individual user&#39;s authentication and permissions.</p><p>This means different users can ask the same type of question while continuing to see only the data and objects they are authorized to access in the underlying system.</p><p>For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Show my available Planning Analytics cubes and help me find the one used for workforce planning.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Query the BigQuery data I have access to and compare it with this TM1 forecast.</span></span></code></pre></div><p>Users do not need to provide their source-system credentials to SPACE when using supported SSO connections.</p><h2 id="turn-technical-logic-into-business-explanations" tabindex="-1">Turn technical logic into business explanations <a class="header-anchor" href="#turn-technical-logic-into-business-explanations" aria-label="Permalink to &quot;Turn technical logic into business explanations&quot;">​</a></h2><p>SPACE AI can help bridge the gap between model developers and business users.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain how the forecast is calculated for a finance user.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Summarize what this allocation process does without using TI terminology.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain why this number changes when the scenario is switched from Budget to Forecast.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a concise explanation of this model logic that I can send to the FP&amp;A team.</span></span></code></pre></div><p>The same underlying model information can be explained differently depending on the audience and purpose.</p><h2 id="ask-how-to-use-space" tabindex="-1">Ask how to use SPACE <a class="header-anchor" href="#ask-how-to-use-space" aria-label="Permalink to &quot;Ask how to use SPACE&quot;">​</a></h2><p>SPACE AI can also answer questions about SPACE itself using the available product documentation.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How can SPACE help me investigate a failed TI process?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How do I create a private subset with the AI Assistant?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How can I compare two Planning Analytics environments?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How do connections and SSO work in SPACE?</span></span></code></pre></div><p>This lets users begin with the task they want to accomplish rather than first finding the correct documentation page or SPACE module.</p><h2 id="build-on-the-conversation" tabindex="-1">Build on the conversation <a class="header-anchor" href="#build-on-the-conversation" aria-label="Permalink to &quot;Build on the conversation&quot;">​</a></h2><p>Many of the most useful workflows combine several of these capabilities. Start with a broad question and refine the task as SPACE AI discovers relevant information.</p><p>For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Why is North America revenue below forecast?</span></span></code></pre></div><p>Then continue:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Break the variance down by product.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Now check whether the largest variance is affected by a rule.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain that rule.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check whether the rule is different in Development.</span></span></code></pre></div><p>Then turn the useful result into something reusable:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Visualize the variance by product as a chart.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Save these results as a private cube view called North America Revenue Variance.</span></span></code></pre></div><p>A single investigation can move from business data to visualization, model logic, environment comparison, troubleshooting, and development while preserving the context of the conversation. Useful analysis results can also become reusable Planning Analytics views rather than remaining only in the chat.</p>',119)]))}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
